const paths={home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',calendar:'M7 3v4M17 3v4M4 10h16M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z',arrow:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 12 6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',chat:'M21 11.5a8.5 8.5 0 0 1-8.5 8.5H3l2-5A8.5 8.5 0 1 1 21 11.5Z',shirt:'m8 3-6 4 3 5 3-2v11h8V10l3 2 3-5-6-4a4 4 0 0 1-8 0Z',wallet:'M20 7H5a2 2 0 0 1 0-4h13v4M3 5v14a2 2 0 0 0 2 2h15V7M20 11h-5v5h5',check:'m5 12 4 4L19 6',image:'M4 3h16v18H4ZM4 16l5-5 4 4 3-3 4 4M9 7h.01',pin:'M12 21s7-6 7-12a7 7 0 0 0-14 0c0 6 7 12 7 12ZM14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',settings:'M4 7h16M4 17h16M9 4v6M16 14v6'};
paths.bell='M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4';
const icon=k=>`<svg class="glyph" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.arrow}"/></svg>`;
if(typeof navigator!=='undefined'&&/Android/i.test(navigator.userAgent))document.documentElement.dataset.platform='android';
const greetings=['Hey, family!','Cousins, assemble.','Who brought the good plates?','Come get your hug.','The group chat, but organized.','Yes, there will be seconds.','We saved you a seat.','Somebody check on the grill.','Family first. Plates second.','A little soul. A lot of family.','We are family.','Your people are right here.','Bring yourself. And a container.'];
let greetingIndex=0;try{greetingIndex=(Number(sessionStorage.getItem('gw-greeting')||-1)+1)%greetings.length;sessionStorage.setItem('gw-greeting',greetingIndex)}catch{}
let greeting=greetings[greetingIndex];let familyTab='people',notificationScope='leaders',readNotices=false;let selectedPeople=['sample-cousin'];const canPostPreview=true;
try{const n=localStorage.getItem('gw-notifications');if(['all','selected','leaders','off'].includes(n))notificationScope=n}catch{}
const serifFonts=['Glass Antiqua','Taviraj','Corben','DM Serif Text'];let serifFont='Glass Antiqua';
function remember(k,v){try{localStorage.setItem(k,v)}catch{}}
try{const t=localStorage.getItem('gw-theme'),f=localStorage.getItem('gw-font'),sf=localStorage.getItem('gw-serif');if(['light','dark'].includes(t))document.documentElement.dataset.theme=t;if(['serif','sans'].includes(f))document.documentElement.dataset.font=f;if(serifFonts.includes(sf))serifFont=sf}catch{}
const $=s=>document.querySelector(s);let view='home',planner=false,liked=false,vote='',shirtChoice='',rsvp='',toastTimer;
const button=(text,action,secondary=false)=>`<button class="button${secondary?' secondary':''}" data-action="${action}">${text}${icon('arrow')}</button>`;
const row=(glyph,title,detail,action)=>`<button class="list-row" data-action="${action}">${icon(glyph)}<span><strong>${title}</strong><p>${detail}</p></span><span class="arrow">${icon('arrow')}</span></button>`;
const postHead=(name,sub,initial='GW')=>`<div class="row post-head"><span class="avatar">${initial}</span><div><strong>${name}</strong><span class="muted">${sub}</span></div></div>`;
function home(){const next=!rsvp?['RSVP for your household','Let us know you’re coming.','rsvp']:!shirtChoice?['Choose your family shirts','Your RSVP is saved. Shirts are next.','shirts']:['Send your share','Your plans are saved. Contributions are next.','contribute'];return `<div class="intro"><div class="eyebrow">Our family, in one place</div><h1 class="greeting">${greeting}</h1></div><section class="card home-hero"><div><span class="badge">The next reunion</span><h2>More time<br>with our people.</h2><p class="muted small">Dates and location are on the way.</p><div style="margin-top:18px">${button('Reunion details','reunion')}</div></div><div><img class="photo" src="${familyPhotos.garden}" alt="Sample photo of a family smiling together outdoors"><p class="photo-caption">Sample photography · Vanessa Loring / Pexels</p></div></section><div class="columns home-grid"><section class="stack" aria-label="Family feed"><div class="feed-label"><h2>Family feed</h2><span class="badge">Family only</span></div><article class="card">${postHead('The planning crew','Sample photo post')}<div class="post-body"><h3>It starts with our people.</h3><p class="small muted" style="margin-top:7px">A place for all our favorite moments.</p></div><div class="post-photo"><img class="photo" src="${familyPhotos.generations}" alt="Sample photo of three generations smiling together"><p class="photo-caption">Sample photography · KATRIN BOLOVTSOVA / Pexels</p></div><div class="post-actions"><button data-action="like" aria-pressed="${liked}">${icon('heart')}${liked?'Loved':'Love'}</button><button data-action="comments">${icon('chat')}Comment</button><button data-action="memories">${icon('image')}All photos</button></div></article><article class="card">${postHead('A little family vote','Sample poll · Pick one')}<h3>What’s on the reunion playlist?</h3><div class="poll">${['The classics','A little bit of everything','Let the cousins DJ'].map((x,i)=>`<button data-vote="${i}" aria-pressed="${vote===String(i)}">${vote!==''?`<span class="bar" style="--pct:${[35,45,20][i]}%"></span>`:''}<span>${x}</span><span>${vote!==''?[35,45,20][i]+'%':icon('plus')}</span></button>`).join('')}</div><p class="small muted" style="margin-top:12px">${vote!==''?'Sample results · Your choice stays in this preview.':'One vote per family member.'}</p></article></section><aside class="home-context"><div class="stack"><section class="card reunion-hub"><h2>Your reunion</h2><div class="next-step"><span><strong>${next[0]}</strong><span class="small muted">${next[1]}</span></span></div><div style="margin:12px 0 20px">${button(next[2]==='rsvp'?'RSVP now':next[2]==='shirts'?'Choose your shirts':'Send your share',next[2])}</div>${row(rsvp?'check':'calendar','Your RSVP',rsvp||'Not answered yet','rsvp')}${row(shirtChoice?'check':'shirt','Family shirts',shirtChoice||'Pick a design and size','shirts')}${row('wallet','Your contribution','Send your share','contribute')}</section></div></aside></div>`}
function reunion(){return `<div class="intro"><div class="eyebrow">Green & White reunion</div><h1>Let’s make memories.</h1><p class="muted">All your reunion details, without the group-chat scroll.</p></div><div class="columns"><div class="stack"><section class="card hero"><span class="badge">In the works</span><h2>Save a little<br>room for family.</h2><div class="row" style="margin:19px 0">${icon('calendar')}<span>Dates to be announced</span></div><div class="row muted">${icon('pin')}<span>Location to be announced</span></div></section><section class="card"><h2 style="margin-bottom:20px">Your plans</h2>${row('calendar','RSVP for your household',rsvp||'One simple reply for everyone','rsvp')}${row('shirt','Choose your shirts',shirtChoice||'One bulk order for the family','shirts')}${row('wallet','Send your share','PayPal or Cash App','contribute')}</section></div><aside class="stack"><section class="card"><h2>The weekend</h2><div class="empty">${icon('calendar')}<p>Good things are coming.</p><p class="small muted">The planning crew will add the schedule here.</p></div></section><section class="card"><h3>A little clarity</h3><p class="small muted" style="margin-top:12px">Shirt choices and contributions stay together. You can see what you selected, what you’ve sent, and what the treasurer has confirmed.</p></section></aside></div>`}
function family(){const tabs=[['people','People'],['memories','Memories'],['tree','Family tree']];return `<div class="intro"><h1>Our family.</h1><p class="muted">People, memories, and the stories that connect us.</p></div><div class="family-tabs" role="tablist" aria-label="Family sections">${tabs.map(([id,label])=>`<button role="tab" id="tab-${id}" aria-selected="${familyTab===id}" aria-controls="family-panel" data-family-tab="${id}">${label}</button>`).join('')}</div><section id="family-panel" role="tabpanel" aria-labelledby="tab-${familyTab}">${familyTab==='people'?`<div class="columns"><section class="card"><h2>Address book</h2><p class="muted" style="margin:12px 0 24px">A trusted place for the details each person chooses to share.</p><div class="directory-empty">${icon('people')}<h3>Start with your own card.</h3><p class="muted small">Add your details, then choose who can see them. No contact information is shared in this preview.</p>${button('Set up my contact card','contact-card')}</div></section><aside class="stack"><section class="card"><h3>Your family profile</h3><p class="small muted" style="margin:12px 0 18px">A familiar face, a little about you, and your place in the family.</p>${button('View your profile','you',true)}</section><p class="note">Contact cards are opt-in. Importing someone’s details will not publish them to the family.</p></aside></div>`:familyTab==='memories'?`<section><div class="section-head"><h2>Shared memories</h2><span class="badge">Sample photos</span></div><div class="memory-grid"><figure><img class="photo" src="${familyPhotos.garden}" alt="Sample family smiling outdoors"><figcaption>Vanessa Loring / Pexels</figcaption></figure><figure><img class="photo" src="${familyPhotos.generations}" alt="Sample photo of three generations"><figcaption>KATRIN BOLOVTSOVA / Pexels</figcaption></figure></div></section>`:`<section class="card tree-later"><img src="tree.svg" width="110" height="96" alt="Green and White oak grove"><h2>Our roots run deep.</h2><p class="muted">The reunion lead’s family research will help shape this space.</p><p class="small muted">Later, family members can submit names, photos, dates, and connections for admins and moderators to review.</p><span class="badge">Planned for a later phase</span></section>`}</section>`}
function you(){return `<div class="intro"><div class="eyebrow">Your little corner</div><h1>Hi, Lauren.</h1><p class="muted">A familiar face in the family.</p></div><div class="columns"><section class="card profile"><span class="avatar">L</span><h2>Lauren</h2><p class="muted small">Profile preview</p><span class="badge">Green & White family</span><p style="margin:22px 0" class="small muted">A short introduction and your family connections will go here.</p>${button('Edit profile','profile',true)}</section><section class="card">${row('calendar','My RSVP',rsvp||'Not sent yet','rsvp')}${row('shirt','My shirts',shirtChoice||'Choose a design','shirts')}${row('wallet','My contributions','Nothing confirmed yet','contribute')}${row('bell','Notifications','Choose who you hear from','notification-settings')}</section></div><section class="card planner-section"><h2 class="list-heading">Planner tools</h2><p class="small muted">Admin / moderator preview</p>${row('settings','Planner overview','Everything in one place','planner')}${row('calendar','Reunion details','Dates, location and schedule','plan-details')}${row('chat','Post an update','Photos, announcements and polls','compose')}${row('shirt','Shirt totals','Manage the family order','shirt-totals')}${row('wallet','Contributions','Review reported payments','review-payments')}</section><p class="creator-credit">Built by <a href="https://loew.fi" target="_blank" rel="noopener noreferrer">Lauren Olivia</a><span>loew.fi</span></p>`}
function shirtSvg(color){return `<svg viewBox="0 0 180 190" aria-hidden="true"><path d="m55 22-42 28 22 37 20-13v97h70V74l20 13 22-37-42-28c-5 15-18 22-35 22S61 37 55 22Z" fill="${color}" stroke="currentColor" stroke-opacity=".12" stroke-width="2"/><image href="tree.svg" x="73" y="68" width="34" height="34"/><text x="90" y="114" text-anchor="middle" fill="${color==='#173c2a'?'#f5f3e8':'#173c2a'}" font-size="10" font-family="sans-serif" font-weight="700">GREEN & WHITE</text></svg>`}
function shirts(){return `<div class="intro"><div class="eyebrow">One family. One bulk order.</div><h1>Wear your roots.</h1><p class="muted">Choose a design and size. The planning crew handles the order together.</p></div><div class="columns"><section class="grid-two"><article class="card shirt-card"><div class="shirt">${shirtSvg('#173c2a')}</div><h3>Forest green</h3><p class="small muted">Concept design</p>${button('Choose this','shirt-green')}</article><article class="card shirt-card"><div class="shirt">${shirtSvg('#f2efdf')}</div><h3>Warm white</h3><p class="small muted">Concept design</p>${button('Choose this','shirt-white')}</article></section><aside class="stack"><section class="card"><h2>Your selection</h2><p style="margin:16px 0" class="muted small">${shirtChoice||'Pick a design to start your household’s shirt list.'}</p><p class="note">Price, order deadline, and available sizes will be confirmed by the planners.</p></section></aside></div>`}
function planning(){return `<div class="intro"><button class="text-button" data-view="you">← Back to You</button><div class="eyebrow">Planner preview · sample data</div><h1>A little less juggling.</h1><p class="muted">Keep the family informed and the reunion moving.</p></div><div class="columns"><div class="stack"><div class="grid-two"><div class="stat"><b>—</b><span>Confirmed attendees</span></div><div class="stat"><b>—</b><span>Shirts requested</span></div></div><section class="card"><h2 style="margin-bottom:20px">Start here</h2>${row('calendar','Reunion details','Set dates, location and schedule','plan-details')}${row('chat','Post an update','Announcements, photos or polls','compose')}${row('shirt','Shirt order','Design and size totals','shirt-totals')}${row('wallet','Contributions','Review reported payments','review-payments')}</section></div><aside class="stack"><section class="card"><h2>Keep it in the family.</h2><p class="muted small" style="margin:14px 0">Members can RSVP, choose shirts, and vote. Admins and moderators publish updates and media first.</p><p class="note">This preview shows the planner tools. In the real app, only authorized roles can access them.</p></section><section class="card"><h3>Payment destinations</h3><p class="small muted" style="margin:12px 0 18px">Only the treasurer can change where contributions go.</p>${button('Preview setup','payment-setup',true)}</section></aside></div>`}
function render(){const routes={home,reunion,family,you,shirts};$('#main').innerHTML=planner?planning():(routes[view]||home)();$('.bottom').innerHTML=[['home','home','Home'],['reunion','calendar','Reunion'],['family','people','Family'],['you','user','You']].map(([v,i,t])=>`<button data-view="${v}" ${((planner&&v==='you')||(!planner&&view===v))?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('');renderProfile();$('#notifications').innerHTML=icon('bell');$('#post-fab').hidden=!canPostPreview;$('#post-fab').innerHTML=icon('plus')+'<span>Post</span>';}
function go(v){if(v==='home'&&view!=='home'){greetingIndex=(greetingIndex+1)%greetings.length;greeting=greetings[greetingIndex]}view=v;planner=false;render();window.scrollTo({top:0,behavior:'auto'})}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}function modal(title,html){$('#sheet-title').textContent=title;$('#sheet-body').innerHTML=html;$('#sheet').showModal()}function close(){$('#sheet').close()}function setTheme(t){document.documentElement.dataset.theme=t;remember('gw-theme',t);renderProfile()}
function toggleTheme(){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')}
function setFont(f){document.documentElement.dataset.font=f;remember('gw-font',f);renderProfile()}
function chooseSerif(f){if(!serifFonts.includes(f))return;serifFont=f;remember('gw-serif',f);setFont('serif')}
function renderProfile(){document.documentElement.style.setProperty('--serif-font',`"${serifFont}", Georgia, serif`);const dark=document.documentElement.dataset.theme!=='light',serif=document.documentElement.dataset.font==='serif';$('#profile-popout').innerHTML=`<div class="profile-summary"><span class="avatar">L</span><span><strong>Lauren</strong><small>Your family profile</small></span></div><button class="button full" data-view="you">${icon('user')}Go to You</button><div class="profile-controls"><div class="control-label">Appearance</div><div class="sliding-control" role="group" aria-label="Color theme" data-selected="${dark?1:0}"><span class="slider" aria-hidden="true"></span><button data-theme-choice="light" aria-pressed="${!dark}">${icon('sun')}Light</button><button data-theme-choice="dark" aria-pressed="${dark}">${icon('moon')}Dark</button></div><div class="control-label">Heading style</div><div class="sliding-control font-control" role="group" aria-label="Heading style" data-selected="${serif?0:1}"><span class="slider" aria-hidden="true"></span><button class="serif-sample" data-font-choice="serif" aria-label="Serif headings" aria-pressed="${serif}">gw</button><button class="sans-sample" data-font-choice="sans" aria-label="Sans serif headings" aria-pressed="${!serif}">gw</button></div><label for="serif-picker">Try a serif · temporary preview</label><select id="serif-picker">${serifFonts.map(f=>`<option ${f===serifFont?'selected':''}>${f}</option>`).join('')}</select></div><div class="profile-shortcuts">${row('calendar','Your RSVP','Update your plans','rsvp')}${row('shirt','Family shirts','Choose your size','shirts')}${row('wallet','Send your share','View contributions','contribute')}</div>`}
function hideProfile(){const pop=$('#profile-popout');if(pop.hidePopover)pop.hidePopover()}

function notificationSettings(){return modal('Notifications',`<p class="muted small">Choose whose updates you want alerts for.</p><div class="notification-choices">${[['all','All Family'],['selected','Selected Family Members'],['leaders','Family Leaders'],['off','Off']].map(([id,label])=>`<button class="list-row" data-notification-scope="${id}" aria-pressed="${notificationScope===id}"><span>${label}</span><span class="arrow">${notificationScope===id?icon('check'):''}</span></button>`).join('')}</div>${notificationScope==='selected'?`<label class="member-choice"><input type="checkbox" data-selected-person="sample-cousin" ${selectedPeople.includes('sample-cousin')?'checked':''}>Sample family member</label><p class="small muted">Real members will appear after sign-in is connected.</p>`:''}<p class="note" style="margin-top:20px">Preferences are saved on this device for the preview. Push delivery is not connected yet. On iPhone, you’ll add the app to your Home Screen before enabling notifications.</p>`)}
function notifications(){const sample=[{kind:'leaders',title:'Welcome from the planning crew',body:'A sample family-leader announcement.'},{kind:'family',title:'A new family memory',body:'A sample photo update from a family member.'}];const shown=sample.filter(n=>notificationScope==='all'||notificationScope==='leaders'&&n.kind==='leaders'||notificationScope==='selected'&&n.kind==='family'&&selectedPeople.length);modal('Notifications',`<div class="row spread"><span class="badge">Sample notifications</span><button class="text-button" data-action="notification-settings">Settings</button></div>${shown.length?shown.map(n=>`<article class="notification-item"><h3>${n.title}</h3><p class="small muted">${n.body}</p><span class="small muted">${readNotices?'Read':'Unread'}</span></article>`).join(''):'<p style="margin:24px 0" class="muted">No updates for this filter.</p>'}${shown.length?button('Mark all read','read-notifications',true):''}`)}
function act(a){if(a==='notifications')return notifications();if(a==='notification-settings')return notificationSettings();if(a==='read-notifications'){readNotices=true;return notifications()}if(a==='contact-card')return modal('Your contact card',`<p class="muted small">Design preview. Nothing entered here is uploaded or shared.</p><label for="contact-name">Name</label><input id="contact-name" autocomplete="name" placeholder="Your name"><label for="contact-email">Email</label><input id="contact-email" type="email" autocomplete="email" placeholder="Optional"><label for="contact-phone">Phone</label><input id="contact-phone" type="tel" autocomplete="tel" placeholder="Optional"><label for="contact-visibility">Who can see these details?</label><select id="contact-visibility"><option>Only me</option><option>Selected family members</option><option>Family leaders</option><option>All approved family members</option></select><p class="note" style="margin-top:20px">Live sharing will require sign-in and your explicit review. This preview does not save contact information.</p>`);
if(a==='memories')return modal('Shared memories',`<p class="small muted">Sample photography for the design preview.</p><div class="gallery-grid" style="margin-top:18px"><img class="photo" src="${familyPhotos.garden}" alt="Family smiling outdoors"><img class="photo" src="${familyPhotos.generations}" alt="Three generations together"></div>`);if(a==='planner'){planner=true;render();window.scrollTo({top:0});return}if(['home','reunion','family','you','shirts'].includes(a))return go(a);if(a==='theme')return toggleTheme();if(a==='like'){liked=!liked;return render()}if(a==='rsvp')return modal('Count us in.',`<p class="muted small">A simple RSVP for your household. Preview only.</p><label for="rsvp-count">How many people?</label><select id="rsvp-count">${[1,2,3,4,5,6,7,8].map(n=>`<option>${n}</option>`).join('')}</select><label for="rsvp-status">Your plans</label><select id="rsvp-status"><option>Planning to come</option><option>Still deciding</option><option>Can’t make it</option></select>${button('Save preview RSVP','save-rsvp')}`);if(a==='save-rsvp'){rsvp=$('#rsvp-count').value+' people · '+$('#rsvp-status').value;render();return modal('RSVP saved',`<div class="step-nav"><span class="current">1. RSVP ✓</span><span>2. Shirts</span><span>3. Contribution</span></div><p class="muted">${rsvp}</p><p class="small muted" style="margin-top:10px">Preview saved for this visit only.</p>${button('Next: family shirts','shirts')}<div style="margin-top:10px">${button('Back to Home','home',true)}</div>`)}
if(a.startsWith('shirt-')&&['shirt-green','shirt-white'].includes(a)){const color=a==='shirt-green'?'Forest green':'Warm white';return modal('Your family shirt',`<p class="muted">${color} · concept design</p><label for="shirt-size">Size</label><select id="shirt-size">${['Youth S','Youth M','Youth L','S','M','L','XL','2XL','3XL'].map(s=>`<option>${s}</option>`).join('')}</select><label for="shirt-quantity">Quantity</label><select id="shirt-quantity">${[1,2,3,4,5].map(n=>`<option>${n}</option>`).join('')}</select><button class="button full" style="margin-top:20px" data-save-shirt="${color}">Save selection</button><p class="small muted" style="margin-top:12px">Sample sizes. No purchase or payment is made.</p>`)}
if(a==='contribute')return modal('Send your share',`<p class="muted small">Your household total will appear here once the planners set the costs.</p><div class="note" style="margin-top:17px">Recipient: not configured. The treasurer’s verified name and handle will be shown before you leave the app.</div><button class="payment-choice" data-action="payment-unset">${icon('wallet')}<span><strong>PayPal</strong><small>Open a link with your amount</small></span></button><button class="payment-choice" data-action="payment-unset">${icon('wallet')}<span><strong>Cash App</strong><small>Open the treasurer’s payment request</small></span></button><p class="small muted" style="margin-top:18px">After sending, report it here. Your status stays “Awaiting confirmation” until the treasurer verifies receipt.</p>${button('Preview “I’ve sent it”','sent-preview',true)}`);if(a==='payment-unset')return toast('Preview only. No payment destination has been connected.');if(a==='sent-preview')return modal('Awaiting confirmation',`<div class="row" style="margin-bottom:15px">${icon('check')}<strong>Reported by you</strong></div><p class="muted">The treasurer checks the payment account and confirms receipt. Opening a payment link never marks your contribution paid.</p><p class="note" style="margin-top:20px">This is a sample status. No money was sent or received.</p>`);
if(a==='payment-setup')return modal('Treasurer setup',`<p class="muted">Connect verified PayPal.Me and Cash App request links, then check the displayed recipient on both services.</p><div class="note" style="margin:20px 0">No links are active in this preview. In the real app, destination changes are restricted to the treasurer and recorded for review.</div>`);if(a==='review-payments')return modal('Confirm contributions',`<p class="muted">No real contributions yet.</p><div class="card" style="margin-top:20px"><span class="badge">Sample status</span><h3 style="margin-top:12px">Awaiting confirmation</h3><p class="small muted" style="margin:12px 0">Check recipient, sender, amount and transaction in the payment service before confirming. A screenshot alone isn’t proof of receipt.</p></div>`);
if(a==='quick')return modal(planner?'Keep things moving':'Your reunion, at a glance',`<div class="stack">${button(planner?'Post an update':'Update your RSVP',planner?'compose':'rsvp')}${button('Choose your shirts','shirts',true)}${button('Send your share','contribute',true)}</div>`);
const details={comments:['Say hello','Member conversations will live below each post. This preview does not send comments.'],connection:['Find your connection','Search for a family member, choose your relationship, and ask them to confirm. Ancestor profiles can be added separately.'],profile:['Your microprofile','Your photo, name, a short introduction, and confirmed family connections. Your contact information stays private by default.'],'plan-details':['The next reunion','Dates, location, schedule and contribution amounts are still to be decided.'],compose:['Keep the family in the loop','Admins and moderators can start with an announcement, a photo or a poll. Publishing is not connected in this preview.'],'shirt-totals':['One bulk order','The planners will see total shirts by design and size, plus each household’s selections. There are no real orders yet.']};if(details[a])modal(details[a][0],`<p class="muted">${details[a][1]}</p>`)}
document.addEventListener('change',e=>{if(e.target.id==='serif-picker')chooseSerif(e.target.value);if(e.target.dataset.selectedPerson){selectedPeople=e.target.checked?[e.target.dataset.selectedPerson]:[]}});document.addEventListener('click',e=>{const ft=e.target.closest('[data-family-tab]');if(ft){familyTab=ft.dataset.familyTab;render();$('#tab-'+familyTab)?.focus?.();return}const ns=e.target.closest('[data-notification-scope]');if(ns){notificationScope=ns.dataset.notificationScope;remember('gw-notifications',notificationScope);notificationSettings();return}const theme=e.target.closest('[data-theme-choice]');if(theme){setTheme(theme.dataset.themeChoice);return}const font=e.target.closest('[data-font-choice]');if(font){setFont(font.dataset.fontChoice);return}const v=e.target.closest('[data-view]');if(v){hideProfile();close();go(v.dataset.view);return}const b=e.target.closest('[data-action]');if(b){hideProfile();if($('#sheet').open&&!['payment-unset'].includes(b.dataset.action))close();act(b.dataset.action);return}const p=e.target.closest('[data-vote]');if(p){vote=p.dataset.vote;render();return}const s=e.target.closest('[data-save-shirt]');if(s){shirtChoice=s.dataset.saveShirt+' · '+$('#shirt-size').value+' × '+$('#shirt-quantity').value;close();render();modal('Shirt choice saved',`<div class="step-nav"><span>1. RSVP</span><span class="current">2. Shirts ✓</span><span>3. Contribution</span></div><p class="muted">${shirtChoice}</p><p class="small muted" style="margin-top:10px">Preview only. No purchase was made.</p>${button('Next: contribution','contribute')}<div style="margin-top:10px">${button('Back to Home','home',true)}</div>`)}});$('#notifications').onclick=notifications;$('#post-fab').onclick=()=>act('compose');$('#close').onclick=close;$('#close').innerHTML=icon('close');$('.brand').onclick=e=>{e.preventDefault();go('home')};render();
